import{_ as t,o as r,c as a,a5 as s}from"./chunks/framework.BmD0ICqc.js";const o="/study/images/network/ip-addresses-and-ports.svg",k=JSON.parse('{"title":"IPアドレス・ポート・ホスト名 — 接続先をどう指定するか","description":"","frontmatter":{"title":"IPアドレス・ポート・ホスト名 — 接続先をどう指定するか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"URLから接続先を読むために、ホスト名、IPv4・IPv6、ポート、TCP・UDPの違いを説明する。ローカルのアドレスと接続をPowerShellで確認する。","aliases":["IPアドレス","IPv4","IPv6","ホスト名","ポート","endpoint","エンドポイント","localhost","loopback","プライベートIP","グローバルIP","一時ポート"],"verification":"IETF・IANA・Microsoftの仕様に照合。掲載した3種のPowerShellコマンドをWindowsで実行確認（2026-11-07）"}},"headers":[],"relativePath":"network/ip-addresses-and-ports.md","filePath":"network/ip-addresses-and-ports.md"}'),i={name:"network/ip-addresses-and-ports.md"};function n(d,e,l,c,h,p){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="ipアドレス・ポート・ホスト名-—-接続先をどう指定するか" tabindex="-1">IPアドレス・ポート・ホスト名 — 接続先をどう指定するか <a class="header-anchor" href="#ipアドレス・ポート・ホスト名-—-接続先をどう指定するか" aria-label="Permalink to &quot;IPアドレス・ポート・ホスト名 — 接続先をどう指定するか&quot;">​</a></h1><p>通信先はIPアドレスとポート番号を組み合わせて指定します。IPアドレスはIPによる配送先を示し、ポート番号はその先でTCPやUDPが受け口を区別するために使います。OSはポートをソケットに対応付け、アプリはそのソケットを通してデータを読み書きします。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-3.1" target="_blank" rel="noreferrer">IPアドレスとポート</a> · <a href="https://www.rfc-editor.org/rfc/rfc768.html" target="_blank" rel="noreferrer">UDPの送信元・宛先ポート</a></p><h2 id="urlに書いてあるもの" tabindex="-1">URLに書いてあるもの <a class="header-anchor" href="#urlに書いてあるもの" aria-label="Permalink to &quot;URLに書いてあるもの&quot;">​</a></h2><p>次は説明用のURLです。<code>example.com</code>は文書の例に使えるドメイン名です。<a href="https://www.rfc-editor.org/rfc/rfc2606.html#section-3" target="_blank" rel="noreferrer">RFC 2606の例示用ドメイン</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com:8443/game/status?room=7</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部分</th><th>意味</th></tr></thead><tbody><tr><td><code>https</code></td><td>使う方式を表すスキーム。HTTPSで通信する。</td></tr><tr><td><code>example.com</code></td><td>接続先を名前で表すホスト名。名前解決でIPアドレスの候補を得る。</td></tr><tr><td><code>8443</code></td><td>このURLで指定した接続先のポート番号。</td></tr><tr><td><code>/game/status</code></td><td>サーバー側で要求する対象を表すパス。</td></tr><tr><td><code>room=7</code></td><td>対象に渡す追加情報を表すクエリー。解釈はそのサービスが決める。</td></tr></tbody></table><p>HTTPSのURLでポートを省略すると、既定の番号は<code>443</code>です。通常のホスト名のA・AAAAレコードを調べるDNSの問い合わせでは、IPv4・IPv6アドレスを得ます。アプリが使うポートはURLの指定やプロトコルの既定値などから決めます。サービスの発見に使うSRVなど、ポート情報を持つ別のDNSレコードもあります。<a href="https://www.rfc-editor.org/rfc/rfc3986.html#section-3" target="_blank" rel="noreferrer">URIの構成</a> · <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-4.2.2" target="_blank" rel="noreferrer">HTTPSのURL</a> · <a href="https://www.rfc-editor.org/rfc/rfc2782.html" target="_blank" rel="noreferrer">DNSのSRVレコード</a></p><h2 id="ipv4とipv6の表記" tabindex="-1">IPv4とIPv6の表記 <a class="header-anchor" href="#ipv4とipv6の表記" aria-label="Permalink to &quot;IPv4とIPv6の表記&quot;">​</a></h2><p><strong>ビット</strong>は0か1かの一つ分です。<strong>IPv4</strong>のアドレスは32ビットで、通常は<code>192.0.2.10</code>のように、0〜255の数を四つ並べて書きます。<strong>IPv6</strong>は128ビットで、<code>2001:db8::20</code>のように16進数をコロンで区切ります。<code>::</code>は連続する0の部分を短く書く表記です。ここでの二つのアドレスは、どちらも文書用の例です。<a href="https://www.rfc-editor.org/rfc/rfc791.html#section-3.2" target="_blank" rel="noreferrer">IPv4のアドレス形式</a> · <a href="https://www.rfc-editor.org/rfc/rfc4291.html#section-2.2" target="_blank" rel="noreferrer">IPv6の表記</a> · <a href="https://www.rfc-editor.org/rfc/rfc5737.html#section-3" target="_blank" rel="noreferrer">IPv4の文書用範囲</a> · <a href="https://www.rfc-editor.org/rfc/rfc3849.html#section-2" target="_blank" rel="noreferrer">IPv6の文書用範囲</a></p><p>IPアドレスはネットワークの接続口である<strong>インターフェース</strong>に割り当てられます。一つのPCに有線とWi-Fiの接続口があり、それぞれにアドレスが付く場合も、一つの接続口が複数のIPv6アドレスを持つ場合もあります。相手へ送る際に使うアドレスは、通信先とOSの経路選択にも関わります。<a href="https://www.rfc-editor.org/rfc/rfc1122.html#section-1.1.1" target="_blank" rel="noreferrer">ホストのインターフェース</a> · <a href="https://www.rfc-editor.org/rfc/rfc4291.html#section-2.1" target="_blank" rel="noreferrer">IPv6のアドレス割り当て</a></p><table tabindex="0"><thead><tr><th>よく見るアドレス</th><th>使う範囲</th></tr></thead><tbody><tr><td>IPv4の<code>10.*.*.*</code>、<code>172.16.*.*</code>〜<code>172.31.*.*</code>、<code>192.168.*.*</code></td><td><strong>プライベートアドレス</strong>。家庭や組織の中で使い、別のネットワークでも同じ番号を使える。</td></tr><tr><td>IPv4の<code>127.0.0.1</code>、IPv6の<code>::1</code></td><td><strong>ループバックアドレス</strong>。通信を自分のホスト内へ戻す。ローカルの開発サーバーなどで使う。</td></tr><tr><td>インターネットへ経路を広報するグローバルアドレス</td><td>インターネットで配送先を指定するために使う。実際に通信できる条件には、経路、ファイアウォール、相手の待ち受けも含まれる。</td></tr></tbody></table><p>プライベートIPv4の端末が外部と通信するときは、ルーターで外側のアドレスへ変換する構成がよく使われます。<code>localhost</code>は自分のホストを指すための名前で、ローカルの名前解決でループバックアドレスに対応します。<a href="https://www.rfc-editor.org/rfc/rfc1918.html#section-3" target="_blank" rel="noreferrer">プライベートIPv4</a> · <a href="https://www.rfc-editor.org/rfc/rfc1122.html#section-3.2.1.3" target="_blank" rel="noreferrer">IPv4ループバック</a> · <a href="https://www.rfc-editor.org/rfc/rfc4291.html#section-2.5.3" target="_blank" rel="noreferrer">IPv6ループバック</a> · <a href="https://www.rfc-editor.org/rfc/rfc6761.html#section-6.3" target="_blank" rel="noreferrer">localhost</a> · <a href="/study/network/nat-and-port-mapping.html">NATとポート変換</a></p><h2 id="ポートと接続の両端を読む" tabindex="-1">ポートと接続の両端を読む <a class="header-anchor" href="#ポートと接続の両端を読む" aria-label="Permalink to &quot;ポートと接続の両端を読む&quot;">​</a></h2><p>ポート番号は16ビットで、<code>0</code>〜<code>65535</code>の値を表せます。アプリがOSへポート<code>0</code>を指定して割り当てを頼むと、OSが利用できる番号を選ぶAPIもあります。TCPの<code>443</code>とUDPの<code>443</code>は、それぞれのプロトコルに属する番号です。アドレス、ポート、TCPかUDPかを合わせて読むと、どの受け口を見ているかを区別できます。<a href="https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml" target="_blank" rel="noreferrer">IANAのサービス名とポート番号</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-bind" target="_blank" rel="noreferrer">Microsoftのbindとポート0</a></p><figure class="study-figure"><img src="'+o+`" alt="クライアント192.0.2.10の一時ポート55000から、サーバー203.0.113.20のTCP 443へ接続する。応答はその両端を逆にして戻る。同じサーバーのTCP 8443とUDP 443は別の受け口になる。" width="760" height="408" loading="lazy"><figcaption>アドレスとポートは説明用の例です。NATを通る場合は、経路上でアドレスやポートが変わることがあります。<a href="/study/images/network/ip-addresses-and-ports.svg" target="_blank" rel="noopener noreferrer">接続の両端の図を拡大</a></figcaption></figure><p>接続の一方の端を<strong>エンドポイント</strong>と呼びます。図ではクライアント側が<code>192.0.2.10:55000</code>、サーバー側が<code>203.0.113.20:443</code>です。クライアント側の番号は、その接続のためにOSが選ぶ<strong>一時ポート</strong>の例です。TCPの接続はローカルと相手の両方のIPアドレス・ポートの組で区別されるので、同じサーバーの<code>443</code>へ複数のクライアントが接続できます。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-4" target="_blank" rel="noreferrer">TCPの接続とソケットの組</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-connect" target="_blank" rel="noreferrer">Microsoftのクライアント側ポート割り当て</a></p><p>IPv6のIPアドレスとポートを一緒に書くときは、<code>[2001:db8::20]:443</code>のように角括弧でアドレスの範囲を示します。IPv6アドレス自体にもコロンが使われるため、ポートの区切りを読み分けられます。<a href="https://www.rfc-editor.org/rfc/rfc3986.html#section-3.2.2" target="_blank" rel="noreferrer">URIのホスト表記</a></p><h2 id="windowsで自分のpcを確認する" tabindex="-1">Windowsで自分のPCを確認する <a class="header-anchor" href="#windowsで自分のpcを確認する" aria-label="Permalink to &quot;Windowsで自分のPCを確認する&quot;">​</a></h2><p>PowerShellで、接続口のアドレス、TCPの接続、UDPのローカル側の受け口を表示できます。下のコマンドは現在の状態を読む操作です。表示される値と件数は、起動中のアプリや通信状態で変わります。<a href="https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-netipconfiguration" target="_blank" rel="noreferrer">Get-NetIPConfiguration</a> · <a href="https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-nettcpconnection" target="_blank" rel="noreferrer">Get-NetTCPConnection</a> · <a href="https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-netudpendpoint" target="_blank" rel="noreferrer">Get-NetUDPEndpoint</a></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetIPConfiguration</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetTCPConnection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LocalAddress</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LocalPort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RemoteAddress</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RemotePort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> State</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetUDPEndpoint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LocalAddress</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LocalPort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OwningProcess</span></span></code></pre></div><p>TCPの<code>LocalAddress</code>と<code>LocalPort</code>が自分側、<code>RemoteAddress</code>と<code>RemotePort</code>が相手側です。<code>State</code>は待ち受け中や接続済みなどの状態を表します。UDPの表示では、ローカル側のアドレス・ポートと、所有するプロセスの番号を確認できます。相手先を指定して送るUDPの動作は、送受信の実践で確かめられます。<a href="/study/practice/network/tcp-loopback-observation.html">TCPソケットの実践</a> · <a href="/study/practice/network/udp-loopback-observation.html">UDPの送受信の実践</a></p><h2 id="関連記事" tabindex="-1">関連記事 <a class="header-anchor" href="#関連記事" aria-label="Permalink to &quot;関連記事&quot;">​</a></h2><ul><li><a href="/study/network/network-basics.html">ネットワークの基本</a></li><li><a href="/study/network/home-network-devices.html">家庭のネットワーク機器</a></li><li><a href="/study/network/dns-resolution.html">DNSと名前解決</a></li><li><a href="/study/network/ip-routing-and-ethernet.html">IPルーティングとEthernetフレーム</a></li></ul>`,23)])])}const g=t(i,[["render",n]]);export{k as __pageData,g as default};
